pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and the sent amount; the rule: reference accepts only 10 ether amounts
    function testFuzz_property(address caller, uint256 sendAmount) public {
        // keep caller non-zero (EOA) to be sensible; allow wide range of amounts
        vm.assume(caller != address(0));

        // fund the caller so they can send arbitrary amounts
        uint256 amount = bound(sendAmount, 0, 100 ether);
        vm.deal(caller, amount);

        // make the call from the fuzzed caller, capturing whether the call succeeded
        bool ok;
        vm.prank(caller);
        try c.f{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract's universal property: only calls with exactly 10 ether succeed.
        // Thus assert that (ok == (amount == 10 ether)). The mutant that changed the require to 5 ether
        // will violate this for amount == 5 ether (ok becomes true there whereas reference expects false),
        // so the test will fail on the mutant for some fuzz input.
        assertTrue(ok == (amount == 10 ether));
    }
}

