import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor (caller) and a timestamp to warp to
    function testFuzz_property(address caller, uint256 ts) public {
        // keep caller as a non-zero address
        vm.assume(caller != address(0));
        // bound timestamp to reasonable range to avoid overflow in vm.warp
        ts = bound(ts, 1, type(uint64).max);

        // fund caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // 1) warp to ts and make a first call with exactly 10 ether
        vm.warp(ts);
        vm.prank(caller);
        c.f{value: 10 ether}();

        // record pastBlockTime after first call
        uint256 t1 = c.pastBlockTime();

        // 2) Call again WITHOUT advancing time (same timestamp). For the reference
        // contract this second call should revert because it requires block.timestamp > pastBlockTime.
        // We capture whether the call succeeds.
        bool ok;
        vm.prank(caller);
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // For the reference contract: the second call MUST NOT succeed when timestamp did not advance.
        // Therefore, assertTrue(!ok) must hold for all inputs. The mutant (which removed the time check)
        // will allow the call to succeed for some inputs (specifically when timestamp unchanged), making
        // this assertion fail for those inputs.
        assertTrue(!ok);

        // Note: single assertTrue reading c's behaviour satisfied above.
    }
