pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address and an initial timestamp warp amount (delta) to create scenarios
    // The property: for any caller and any non-negative warpDelta, if we perform two fallback calls
    // both sending exactly 10 ether, and we ensure the second call happens at a strictly later
    // timestamp (vm.warp increased), then the reference contract will have updated pastBlockTime
    // on the first call only if time had advanced; specifically after the second call, pastBlockTime
    // must equal the later block.timestamp (so it strictly increases when time advances). The mutant
    // that removed the time-check can make pastBlockTime equal to the earlier block.timestamp even
    // when time did not advance and will break the intended monotonic behavior for some inputs.
    function testFuzz_property(address caller, uint256 warpDelta) public {
        // keep caller usable as an EOA in VM
        vm.assume(caller != address(0));
        // bound warpDelta to a reasonable range to avoid overflow in vm.warp
        warpDelta = bound(warpDelta, 1, 1 days);

        // fund caller so it can send 10 ether
        vm.deal(caller, 10 ether);

        // First call at current block timestamp
        vm.prank(caller);
        c.fallback{value: 10 ether}();

        // advance time by warpDelta to ensure block.timestamp strictly increases
        vm.warp(block.timestamp + warpDelta);

        // Second call at later timestamp
        vm.prank(caller);
        c.fallback{value: 10 ether}();

        // The general rule to assert: after the second call, pastBlockTime equals the current block.timestamp
        // (i.e., the contract updated pastBlockTime to the later timestamp). The reference satisfies this
        // for all admissible inputs; the mutant that removed the time-check can be induced to violate it
        // for some inputs (it allows overwriting inappropriately), so the fuzz will find such a case.
        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}

