    function testFuzz_property(address caller, uint32 timeOffset) public {
        // keep caller non-zero
        vm.assume(caller != address(0));
        // bound the timeOffset to a reasonable range so vm.warp won't overflow
        uint32 tOff = uint32(bound(timeOffset, 0, 1000));

        // Fund the caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // 1) set an initial time and call fallback with exactly 10 ether once
        vm.warp(1 + tOff); // initial time > 0
        vm.prank(caller);
        // call fallback by low-level call to trigger payable fallback
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "initial call failed");

        uint256 first = c.pastBlockTime();

        // 2) keep the same block.timestamp (no warp) and call again with exactly 10 ether
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        require(ok2, "second call failed");

        uint256 second = c.pastBlockTime();

        // GENERAL RULE (to assert): In the correct contract, if block.timestamp did NOT advance between two valid fallback calls, pastBlockTime must remain equal to the previous value (i.e., it must NOT be updated to a newer value when timestamp hasn't increased).
        // This assertion reads the public getter pastBlockTime on c exactly once (via second) and compares to first.
        // The mutant that removed the time-order check can update pastBlockTime even when timestamp is unchanged, so for some inputs the two values will differ and the test will fail on the mutant.
        assertTrue(second == first);
    }
}

