pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: a caller address and a block number to decide the branching condition.
    // We must also fuzz a timestamp to satisfy the timestamp monotonicity requirement.
    function testFuzz_property(address caller, uint256 targetBlock, uint256 timestmp) public {
        // admissible domain: caller must be non-zero and targetBlock within reasonable bounds
        vm.assume(caller != address(0));
        // bound targetBlock and timestmp to avoid absurd values while keeping wide search
        targetBlock = bound(targetBlock, 1, type(uint64).max);
        timestmp = bound(timestmp, block.timestamp + 1, block.timestamp + 1 days);

        // Fund the caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // Warp to the chosen timestamp (must be > pastBlockTime which starts at 0)
        vm.warp(timestmp);

        // Roll to the chosen block number so branch block.number % 15 decision is controllable
        vm.roll(targetBlock);

        // Make the call from the fuzzed caller, sending exactly 10 ether as required by C
        vm.prank(caller);
        c.fallback{value: 10 ether}();

        // After the call, the reference contract has the invariant:
        // - if block.number % 15 == 0 then it transferred its entire balance to caller -> address(c).balance == 0
        // - otherwise it kept the funds -> address(c).balance == 10 ether
        // We assert that address(c).balance is either 0 or 10 ether and, crucially, that it equals
        // 0 iff block.number % 15 == 0. This general rule holds for the reference but the mutant
        // inverts the condition and thus will fail for inputs where block.number % 15 == 0 (or != 0).

        bool cond = (block.number % 15 == 0);
        // read c's observable state
        uint256 bal = address(c).balance;

        // single assertion: for the correct contract, bal == 0 iff cond is true; we assert that equivalence
        assertTrue((bal == 0) == cond);
    }
}

