pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // helper depositor account
    address depositor = address(0xBEEF);

    function setUp() public {
        c = new C();
        // fund depositor so it can send 10 ether
        vm.deal(depositor, 100 ether);
    }

    // fuzz the block number (to hit divisible-by-15 case) and a timestamp increment
    function testFuzz_property(uint256 fuzzBlockNumber, uint256 fuzzTimestampIncrement) public {
        // keep block number reasonable and allow hitting the divisible-by-15 branch
        // ensure block number >=1
        uint256 bn = bound(fuzzBlockNumber, 1, type(uint256).max - 1);
        // ensure timestamp increment is at least 1 (require block.timestamp > pastBlockTime)
        uint256 dt = bound(fuzzTimestampIncrement, 1, 1 days);

        // advance to desired block number and set timestamp
        // can't directly set block number, but we can set block.timestamp and roll blocks by warp + roll
        vm.warp(block.timestamp + dt);
        // roll to a block number that is divisible by 15 to trigger the forwarding behavior
        // choose nearest multiple of 15 >= bn
        uint256 targetBlock = ((bn + 14) / 15) * 15;
        // bound targetBlock to at least current block + 1
        if (targetBlock <= block.number) {
            targetBlock = block.number + 1 + (15 - ((block.number + 1) % 15));
        }
        vm.roll(targetBlock);

        // ensure caller has funds and will send exactly 10 ether
        vm.deal(depositor, 100 ether);
        // capture contract balance before the call
        uint256 before = address(c).balance;

        // make the payable fallback call from depositor sending exactly 10 ether
        vm.prank(depositor);
        c.f{value: 10 ether}();

        // After successful reference behavior when block.number % 15 == 0,
        // the contract should have forwarded its entire balance to the caller, leaving balance == 0.
        // This is the single asserted universal property: for this admissible input the reference yields zero balance.
        assertTrue(address(c).balance == 0);
    }
}
